-- Money x100 (batch 10, docs/plans/ECONOMY_SCALE.md): one table per file, so each runs exactly once.
UPDATE eco_ledger SET amount = CASE WHEN amount > 92233720368547758 THEN 9223372036854775807 ELSE amount * 100 END, from_balance = CASE WHEN from_balance > 92233720368547758 THEN 9223372036854775807 ELSE from_balance * 100 END, to_balance = CASE WHEN to_balance > 92233720368547758 THEN 9223372036854775807 ELSE to_balance * 100 END WHERE currency = 'money';
